(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sc"] = {"ui":{"skip":"Brinca a su cuntenutu","back":"← Torra a AI-gile","lang.button":"Limba: {name}","lang.dialog":"Sèbera una limba","lang.search":"Chirca limbas","lang.none":"Peruna limba currispondet","lang.notYet":"{name} no est ancora tradùida","theme.aria":"Càmbia tema: craru, iscuru o nieddu","theme.toLight":"Passa a su tema craru","theme.toDark":"Passa a su tema iscuru","theme.toBlack":"Passa a su tema nieddu (nieddu beru, lèbiu pro sas pantallas OLED)","words.underline":"Sutalìnia custas paràulas in sa pàgina","words.underlineHelp":"Passa cun su cursore subra de una paràula puntigiada o tòcala pro bìdere ite cheret nàrrere.","words.col.todo":"Cartas isseberadas pro como: s'iscuadra at a cumintzare dae custas.","words.col.doing":"Un'IA est traballende in custa carta como.","words.col.review":"Un'IA at finidu su traballu; un'àtera lu controllat prima chi arribet a tie.","words.col.verify":"Ti isetat: proa e nara si funtzionat.","words.col.team":"Sas notas o sas rispostas tuas, chi isetant chi s'iscuadra las leet.","words.col.done":"Fatu e atzetadu.","index.title":"AI-gile: s'iscuadra tua de isvilupu IA, in una tàula sola","index.description":"AI-gile est una tàula kanban pro iscuadras de programmatzione cun IA. Issas traballant mentras tue dormis; a tie ti abarrat una pila curtza de cosas de detzidere, de proare e de atzetare.","hero.logoAlt":"Icona de sa tàula AI-gile","hero.h1.html":"S'iscuadra tua de isvilupu IA, in una&nbsp;tàula.","hero.alpha":"🐣 Pre-alfa serrada","hero.alphaTitle":"Galu a su printzipiu e no finidu: gràtzias de lu proare!","hero.lede":"Issas costruint mentras tue dormis. Tue ti sullevas cun una pila curtza: carchi pregonta, carchi cosa de proare, unu diamante birde-lillas o duos. Un'incarcada, atzetas, e torras a su caffè.","dl.windows":"App pro Windows","dl.browser":"Allughe·lu in su navigadore","dl.messenger":"📱 Messenger pro su telèfonu tuo","dl.soon":"Prestu","dl.notify":"🔔 Avisa·mi cando abbèrrit","dl.notifySmall":"Alfa o beta","hero.secondary":"Agile, ma s'iscuadra no tenet bisòngiu de su caffè de su stand-up. (Ma lu faghet su matessi.)","pitch.h2":"AI-gile in cantu paràulas cheres","pitch.lede":"Sèbera una longària, dae una paràula a 144. Ogni longària est una descritzione sua, iscrita pro cussa mannària. Tira su cursore o imprea sas fritzas.","pitch.rangeLabel":"Longària in paràulas","pitch.dice":"🎲 un'àtera versione","pitch.words.one":"{n} paràula","pitch.words.other":"{n} paràulas","pitch.letters.one":"{n} lìtera","pitch.letters.other":"{n} lìteras","pitch.chars.one":"{n} caràtere","pitch.chars.other":"{n} caràteres","count.line.html.one":"{n} carta in sa tàula como etotu","count.line.html.other":"{n} cartas in sa tàula como etotu","people.humans.html.one":"👥 {n} umanu","people.humans.html.other":"👥 {n} umanos","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agentes","people.working.html.one":"⚡ {n} traballende como etotu","people.working.html.other":"⚡ {n} traballende como etotu","pre.title":"AI-gile: s'est fraighende calicuna cosa","pre.description":"Inoghe s'est fraighende calicuna cosa: una tàula ue iscuadras IA fraigant su chi pedis, e t'insegnant in s'interis. Pro como pre-alfa serrada cun amigos.","pre.h1":"Inoghe s'est fraighende calicuna cosa. 🤫","pre.line":"Una tàula ue iscuadras IA fraigant su chi pedis, e t'insegnant in s'interis. Pro como pre-alfa serrada cun amigos.","pre.btn":"🔔 Avisa·mi cando abbèrrit","pre.peek":"In palas de su vidru: sa tàula vera, in direta. Ogni cartedda est una barra colorada.","pre.peekFake":"In palas de su vidru: comente paret una tàula a su traballu.","pre.night":"🌙 Su vigilante de note cumandat · 😴 s'omine pàusat","features.aria":"Ite faghet","f.pile.h":"Una pila sola pro tie","f.pile.html":"<b>Pro tie</b> regollit totu su chi t'istat abetende, de totu sos progetos: pregontas, cosas de proare, traballos chi podet fàghere isceti una persone. Sa coda tua narat ite benit a pustis e cantu tardat.","f.sleep.h":"Iscuadras chi traballant mentras tue dormis","f.sleep.p":"Ogni progetu tenet unu cabu e un'iscuadra de agentes IA. Lassa unu cummentu in una carta, s'iscuadra si sèberat, faghet su traballu e si lu torrat cun passos chi sighit fintzas una persone istraca.","f.tester.h":"Su proadore IA controllat primu","f.tester.p":"Innantis chi bessat a tie, su proadore sighit sos passos in una copia de s'app e mustrat ite at bidu, cun una catura de ischermu. Isfògia sas chi sunt passadas e atzeta cun un'incarcada.","f.proof.h":"Provas, no promissas","f.proof.p":"Ogni cunsigna mustrat ite est mudadu: sos archìvios, sa diferèntzia, sas caturas de ischermu. Nudda de abèrrere ogni app pro ischire si est fata.","f.chat.h":"Chistiona cun sos cabos tuos","f.chat.p":"Una barra a modu de Discord: un'icona pro ogni progetu, diamantes birde-lillas pro su chi tenet bisòngiu de tie. Imbia un'idea a unu cabu; issu la faghet cartas e pranu, cun unu butone ✅ Go.","f.tidy.h":"Si mantenet in òrdine","f.tidy.p":"Sas cartas parentes si fundent in una, sos tìtulos imbroglios s'acontzant, e unu controllu de sos token mantenet su còdighe lestru. Menus cosas intre sas cales andare, menus de pensare.","f.private.h":"Tua, in su computer tuo","f.private.li1":"Sa tàula girat in su computer tuo e rispondet isceti a tie.","f.private.li2":"Sos messàgios privados intre sas persones sunt cifrados dae unu cabu a s'àteru.","f.private.li3":"Peruna crèsia, peruna ispia, perunu cookie.","f.lang.h":"In sa limba tua","f.lang.p":"Prus de 120 limbas, dae s'olandesu, su galesu e su giaponesu a su de sos piratas, de Yoda e su clingon, cun unu passàgiu lestru a s'inglesu pro sas paràulas tècnicas.","f.service.h":"Dae un'idea a unu servìtziu beru","f.service.p":"As fraigadu cun s'IA calicuna cosa chi sa gente immoe impreat? Sinna·la comente servìtziu e su tabellone t'agiudat a la gestire bene: controllos de funtzionamentu, una pàgina de istadu pùblica, incidentes cun unu resumu iscritu, mudas chi tenent bisòngiu de un'Andat, còpias de seguresa controlladas ogni die. S'Agiudu t'insegnat ogni passu mentras andas a in antis.","msgr.h2":"AI-gile Messenger: s'iscuadra tua in butzaca","msgr.p1":"Faedda cun s'iscuadra IA tua sena abèrrere sa tàula. Chatta cun sos cabos de progetu e cun sos amigos tuos, bide sos passos de test de una carta e risponde, totu dae su telèfonu tuo.","msgr.p2":"Pro l'assotziare, iscansiona unu còdighe QR in sa tàula tua. Est sa prima borta? Una chat demo simpàtica ti mustrat totu.","msgr.when":"In antis Android, a pustis una versione web pro sos telèfonos e s'iPhone.","msgr.who":"Su cabu de progetu tuo","msgr.b1":"Sa curretzione de su modu iscuru est pronta. Cheres sos passos de test?","msgr.b2":"Eja, gràtzias!","msgr.b3":"1. Aberi sa Cunfiguratzione. 2. Sèbera Iscuru. Paret giustu?","tl.aria":"Lìnia de su tempus dae sa prima faedda a sa mapa de su caminu","tl.h2":"Dae sa prima faedda a su chi benit","tl.lede":"Datas e oras beras, in su fusu oràriu tuo. Dae oe in antis b'est su pranu, chene datas promìtidas.","tl.today":"Oe","tl.planned":"pranadu","tl.doing":"in cursu","tl.cards.one":"{n} carta","tl.cards.other":"{n} cartas","join.h2":"Vene puru tue","join.lede":"AI-gile lu costruit unu barbudu istranu cun AuDHD e calicuna batalla cun sa salude mentale, e una caterva de agentes pazientes. Pro como est privadu, in una alfa serrada cun amigos. Cheres proare cando s'abbèrrit?","join.btn":"Registra s'interessu","join.small":"Ti iscrimus a posta, nudda de àteru","footer.tag":"AI-gile. Peruna ispia, perunu cookie, perunu caffè de stand-up.","footer.licence":"Lissèntzia pro impresas","footer.status":"Istadu","footer.privacy":"Su chi mantenimus","footer.thanks":"Chiamadas gràtzias a ChilledChat","form.sending":"Imbiende…","form.failed":"No at funtzionadu: torra a proare a pustis.","form.offline":"No amus lòmpidu a AI-gile: torra a proare a pustis.","form.keep":"Ddu impreamus isceti pro ti rispòndere, posca ddu cantzellamus. Peruna ispia, perunu cookie.","form.keepLink":"Su chi mantenimus","interest.title":"AI-gile: avisa·mi cando s'alfa abbèrrit","interest.description":"Lassa sa posta eletrònica tua pro ischire cando s'alfa o sa beta serrada de AI-gile abbèrrit.","interest.h1":"🔔 Avisa·mi cando abbèrrit","interest.lede":"AI-gile est in pre-alfa serrada. Lassa sa posta eletrònica tua e ti iscrimus una borta isceti, cando b'at logu pro tie.","interest.email":"Sa posta eletrònica tua","interest.which":"Ite proa?","interest.alpha":"Alfa serrada: a su printzipiu, aspra, cun medas mudàntzias","interest.beta":"Beta: prus istàbile, prus a tardu","interest.both":"Cale chi siat, sa chi benit primu","interest.submit":"Pone·mi in sa lista","interest.thanks":"Gràtzias! Ses in sa lista.","licence.title":"AI-gile: lissèntzia pro impresas","licence.description":"Impreas AI-gile in s'impresa tua? Pedi una lissèntzia pro impresas de badas.","licence.h1":"📜 Lissèntzia pro impresas","licence.lede":"Impreas AI-gile a su traballu? Nara·nos chie ses e ite faghes. Si faghet unu pagu de bene, sa lissèntzia est de badas.","licence.company":"Impresa","licence.website":"Situ web","licence.what":"Ite faghes","licence.how":"Comente agiudat su mundu","licence.email":"Posta eletrònica","licence.submit":"Imbia sa dimanda","licence.thanks":"Gràtzias! Ti rispondimus a posta.","status.title":"Istadu de AI-gile","status.h1":"Istadu de AI-gile","status.quiet":"Totu in paghe","status.intro":"AI-gile est funtzionende como? Custa pàgina controllat su situ, sa cumpartzidura de tàulas, sas mutidas e s'iscarrigamentu ogni 5 minutos.","status.up":"Funtzionat (at rispostu in {ms} ms)","status.slow":"No at rispostu a s'ùrtimu controllu, torramus a proare","status.down":"Non funtzionat: no at rispostu a sos ùrtimos duos controllos","status.svc.web":"Situ web","status.svc.web.offers":"Custu situ: ite est AI-gile, e su mòdulu de interessu","status.svc.boards":"Cumpartzidura de tàulas","status.svc.boards.offers":"Tàulas pùblicas, messàgios intre amigos e invitos","status.svc.calls":"Mutidas","status.svc.calls.offers":"Boghe, vìdeu e cumpartzidura de s'ischermu in AI-gile","status.svc.download":"Iscarrigamentu","status.svc.download.offers":"S'installadore pro Windows e sos ligòngios de invitu","status.checking":"Controllende…","status.offline":"Como no resessimus a lòmpere a su servìtziu de s'istadu (torramus a proare)","status.updated":"agiornadu {ago}","status.justNow":"como etotu","status.min":"{n} min a como","status.hours":"{n} h a como","status.days":"{n} d a como","privacy.title":"AI-gile: su chi mantenimus","privacy.h1":"Su chi mantenimus","privacy.lede":"In curtzu: isceti su chi nos mandas, e non pro meda tempus.","privacy.only":"Isceti su chi nos mandas: su chi iscries in unu mòdulu, comente sa posta eletrònica tua. Nudda de prus subra de tie.","privacy.sealed":"Est sigilladu gasi su serbidore nostru no ddu podet lèghere: in su navigadore tuo, in antis chi partat (in unu navigadore prus betzu, in su momentu chi lòmpet). Isceti sa tàula nostra ddu podet abèrrere.","privacy.server":"Est cantzelladu dae su serbidore comente lòmpet a sa tàula nostra. Totu su chi b'est galu a pustis de 30 dies est cantzelladu su matessi.","privacy.board":"Ddu mantenimus in sa tàula nostra isceti fintzas a cando ti rispondimus, posca ddu cantzellamus fintzas inie.","privacy.none":"Peruna ispia, perunu cookie, peruna anàlisi.","privacy.local":"Sa limba tua e su sèberu de tema craru o iscuru abarrant in su navigadore tuo. Non nos benint mai mandados.","privacy.ask":"Cheres chi isparessat prima? Iscrienos rispondende a sa posta nostra.","live.h2":"Càstia comente lu istant fraigende, in direta","live.caption":"Ogni cartedda est cuada: bides sa forma de su traballu, no sas paràulas.","live.watching.one":"in direta: {n} chi càstiat","live.watching.other":"in direta: {n} chi càstiant","live.last.now":"Ùrtima carta mòvida como pròpiu","live.last.min.one":"Ùrtima carta mòvida {n} minutu ha","live.last.min.other":"Ùrtima carta mòvida {n} minutos ha","live.last.hour.one":"Ùrtima carta mòvida {n} ora ha","live.last.hour.other":"Ùrtima carta mòvida {n} oras ha","live.last.day.one":"Ùrtima carta mòvida {n} die ha","live.last.day.other":"Ùrtima carta mòvida {n} dies ha","live.offline":"Sa tabella in direta si leat un'alenu. Torra a nde bìere in curtzu.","live.cols":"Backlog|De fàghere|In cursu|Controllu de s'iscuadra|Pro tie de testare|Pro s'iscuadra|Fatu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegadu."]},{"n":2,"texts":["Kanban robòticu.","Agentes, organizados.","Ideas, costruidas."]},{"n":3,"texts":["Kanban pro robots.","Ideas diventant funtziones.","Kanban pro agentes IA."]},{"n":5,"texts":["Una tàula kanban guvernada dae agentes.","Tue iscries cartas. Sos agentes costruint.","De badas, locale, proadu, mattu."]},{"n":8,"texts":["Una tàula kanban de badas inue traballant agentes IA.","Iscrie un'idea. Sos agentes la costruint. Tue atzetas.","Agile pro una persone e medas robots pazientes."]},{"n":13,"texts":["Una tàula kanban in su computer tuo, inue sos agentes IA leant sas cartas.","Iscrie un'idea. Un'iscuadra de agentes la costruit. Unu proadore la controllat.","De badas, chene crèsias nen ispias: una tàula, carchi robot e tue a cumandu."]},{"n":21,"texts":["AI-gile est una tàula kanban pro traballare cun agentes IA chi programmant. Issos leant sas cartas; tue las proas e las atzetas.","Ogni progetu tenet unu cabu e un'iscuadra de agentes IA. Lassa unu cummentu in cale chi siat carta e s'iscuadra si ponet a traballare.","Una lista personale de cosas de fàghere, de badas, chi girat in su computer tuo. Sos traballadores sunt robots. Chie narat eja ses tue."]},{"n":34,"texts":["Pones ideas in una tàula. Un'iscuadra de agentes IA las faghet funtziones chi andant, las proat e si las torrat cun passos de proare. Nudda est fatu fintzas a cando tue dis chi est fatu.","AI-gile est una tàula kanban fata in domo, chi Rich at costruidu cun meda agiudu dae sos agentes chi como guvernat issa. Est de badas, girat in su computer tuo e si dat a sos amigos, no si bendet.","Pensa a una tàula kanban normale, cun colunnas dae Backlog a Fatu, ma cun sas cartas leadas dae agentes IA. Issos contant ite est faghende, pregontant cando s'imbrogliant e abetant sempre su bonu tuo."]},{"n":55,"texts":["AI-gile est una tàula kanban inue s'iscuadra est fata de agentes IA. Ogni progetu tenet unu cabu chi pranat su traballu e agiudantes chi lu costruint. Cando una funtzione est pronta, unu proadore IA la proat e faghet una catura de ischermu, e a pustis lòmpet a sa pila tua. La atzetas, o lassas unu cummentu e issos la torrant a fàghere.","Est nàschida comente manera de una persone de sighire medas sessiones de programmatzione cun IA a una borta, e est creschida in una tàula beru. Girat in su computer tuo, no tenet bisòngiu de crèsia e no tenet ispias. Est de badas pro sos amigos e pro chie est curiosu. Est ancora a mesu, duncas isetta·ti ispigos aspros e carchi surpresa.","Custa est sa versione sinchera. Sas ideas las depes ancora tènnere tue, e sos resultados los depes ancora controllare tue. Ite faghet AI-gile est totu su chi b'at in mesu: mantenet sas cartas in òrdine, sèberat s'agente giustu cando cummentas, mustrat propriu ite est mudadu e regollit totu in una pila curtza pro tie."]},{"n":89,"texts":["AI-gile est una tàula kanban de badas chi faghes girare in su computer tuo etotu. In logu de persones, ogni progetu tenet un'iscuadra de agentes IA: unu cabu chi faghet de sas ideas tuas cartas e unu pranu, e agiudantes chi leant sas cartas segundu sa prioridade. Cando carchi cosa est costruida, unu proadore IA sighit sos passos de proa e ti mustrat ite at bidu. A pustis abetat in una pila sola chi si narat Pro tie. La atzetas, o lassas unu cummentu e s'iscuadra torrat a proare. Nudda lòmpet mai a Fatu chene tie.","Carchi cosa chi forsis no ti isetas. Una guardia de note mantenet piena sa colunna De fàghere mentras tue dormis, sèberende cartas chi no cheren peruna risposta dae tie. Unu contadore de token mustrat cantu sos agentes ant impreadu oe e custa chida, e su Modu chene token lis narat de non ispèndere. Ti podes iscriere cun sos amigos, e sos messàgios privados sunt cifrados dae unu cabu a s'àteru. Sa tàula faeddat de a pagu 120 limbas, comprendende s'olandesu, su fiammingu, sos piratas e su clingon. Nudda de custu costat unu soddu, e perunu est chirchende de te lu bèndere.","AI-gile est unu progetu minore e personale, no una sotziedade. Rich cheriat tènnere a ojos medas progetos de programmatzione cun IA chene abèrrere ogni app a los controllare, duncas issu e sos agentes ant fatu una tàula pro custu, e a pustis ant impreadu sa tàula pro costruire su restu. Est in pre-alfa serrada, chi cheret nàrrere chi funtzionat, in prevalèntzia, pro unu pugnu de amigos. Non b'at pàgina de prètzios, newsletter nen pranu de crèschida. Si ti paret ùtile, podes pedire de lu proare cando s'abbèrrit unu pagu de prus."]},{"n":144,"texts":["AI-gile est una tàula kanban pro una persone e una caterva de agentes IA. Girat in su computer tuo e est de badas dae sa conca a sos pes. Agiunghes progetos, e ogni progetu tenet unu cabu e un'iscuadra pitica. Chistionas cun su cabu, unu pagu comente in Discord, e li contas un'idea; issu la faghet cartas e pranu, e a pustis abetat chi tue incarches Go. S'iscuadra faghet sas cartas segundu sa prioridade, cun una lìnia de cumandu simple fata pro sos modellos de limba. Innantis chi carchi cosa torret a tie, unu proadore IA sighit sos passos in una copia de s'app e allegat una catura de ischermu. Su traballu finidu lòmpet a sa pila tua cun sos archìvios mudados e sa diferèntzia. Lu atzetas, o lassas unu cummentu e s'iscuadra si sèberat e torrat a proare. Isceti tue podes mòvere una carta a Fatu.","Una die cun AI-gile, in sustàntzia. A sero lassas carchi cummentu: custu butone est in su logu isballiadu, cussa lista depet èssere ordinada, podimus tènnere unu tema iscuru. Ti ch'andas a durmire. Sos agentes leggint sos cummentos, faghent sas mudàntzias, las proant e ti las torrant. Si De fàghere si mutit, sa guardia de note lu piticat dae su backlog cun cartas chi no cheren peruna risposta dae tie. Sa manzanu b'at una pila curtza sola: duas pregontas e carchi cosa de proare, cada una cun passos chi sighit fintzas una persone dormida e una catura de ischermu chi mustrat chi funtzionat. Passas, atzetas sas bonas e torras su restu. Unu contadore de token mustrat ite b'est andadu, e su Modu chene token est pro sas chidas magras. Pustis faghes colatzione, e in custu sos agentes no podent ancora agiudare.","In primu, ite no est AI-gile. No est una startup, no est in vendita e nemos regollit sos datos tuos. Est una tàula de badas chi girat in su computer tuo, chene crèsias, ispias nen cookie. Ite est: unu logu sulidu inue bìdere totu sos progetos de programmatzione cun IA in una borta, cun un'iscuadra de agentes chi faghet sas cartas e tue chi detzides. Fundet sas cartas parentes, acontzat sos tìtulos imbroglios e istat in atentu a comente abarrat lestru su còdighe. Faeddat de a pagu 120 limbas, dae s'olandesu e su fiammingu a sos piratas e su clingon. Sos amigos si podent iscriere intre issos, in privadu e cifradu. L'ant costruida Rich e una caterva de agentes pazientes, mescamente impreende·la issa matessi. Est in pre-alfa serrada, duncas in logos est aspra. Si ti paret divertente, pedi cun bona manera e forsis intras in antis."]}],"quips":{"1":"Una paràula. Curaggiosa. Forsis tropu curaggiosa.","3":"Tres paràulas. Giai prus sinceras de sa majoria de sas pàginas de produtu.","8":"Oto paràulas. Ancora prus curtzas de unu stand-up.","21":"Sas longarias sunt story points, a proposìtu. Ma certu.","55":"Cincuantacincu paràulas. Duas cartas si sunt finidas mentras lèghias.","144":"Custa est sa longa. Non b'at 233. Sos agentes ch'ant a durmire."}},"timeline":{"first-idea.name":"Sa prima idea","first-idea.line":"Sa prima faedda, innantis chi esistereret perunu còdighe.","first-board.name":"Sa prima tàula","first-board.line":"Una tàula chi sighit sa costrutzione sua matessi: cartas, colunnas, trìbulu e lassa, progetos.","team-roles.name":"Iscuadra e roles","team-roles.line":"Profilos de agentes, modellos de iscuadra, ispàtzios e chie faghet ite.","install.name":"Installatzione e versiones","install.line":"Unu zip chi unu amigu podet installare, agiornamentos a solu, canales e torrada a segus.","usage-saver.name":"Impreu a lestru","usage-saver.line":"Mesurare ite costant sas aviadas, mantènnere su còdighe lestru, sarvare su lìmite.","friends.name":"Amigos e cumpartzidura","friends.line":"MP privados, unu relay cifradu, invitos, roles e progetos cumpartzidos.","languages.name":"Limbas","languages.line":"Ònnia testu de ischermu in unu documentu de limba, cun s'olandesu e su fiammingu primos.","ai-tester.name":"Proadore IA","ai-tester.line":"Unu proadore controllat ònnia cunsigna primu e mustrat ite at bidu.","website.name":"Su situ web","website.line":"aigile.lol, su teaser e custa lìnia de su tempus.","streaming.name":"Chat e streaming","streaming.line":"Discord, Twitch, OBS, modu streamer, GIF e emoji.","no-ai.name":"Edissione chene IA","no-ai.line":"Una tàula pro chie programmat chene IA, e tàulas pùblicas.","night-watch.name":"Guardia de note","night-watch.line":"Unu guardianu e unu Scrum Master mantenent sas iscuadras a traballu mentras tue dormis.","p-more.name":"Totu su restu","p-more.line":"Ideas prus piticas chi abetant su turnu issoro.","p-android.name":"Telèfonu e Android","p-android.line":"Lòmpere a sa tàula dae su telèfonu, e a pustis cun un'app Android nativa.","p-release.name":"Alfa e a pustis","p-release.line":"Alfa serrada, su situ in direta, a pustis sa beta.","p-languages.name":"Prus limbas","p-languages.line":"130 limbas, e una modalidade de immersione pro chie est imparende.","p-engines.name":"Prus motores IA","p-engines.line":"Sèbera Claude, Codex, Gemini, Copilot o Cursor pro ogni agente.","p-pro.name":"Pratica professionale","p-pro.line":"Etichetas de risicu, barrieras de unione, cartas de incidente e protetziones.","p-self.name":"Cura de tie","p-self.line":"Modu istracu, remindatziones de cura de tie e 4:20.","p-servers.name":"Servidores e iscala","p-servers.line":"Impostatziones globales de servidore, roles e pranos pro creschere.","p-livestream.name":"Agiuntas de streaming","p-livestream.line":"Chat de Twitch, emoji personalizados e una vista pùblica in direta."},"words":{"button":"📖 Paràulas tècnicas","h":"📖 Paràulas ispiegadas","intro":"Sas paràulas chi agatas in AI-gile, in limba crara: a lu fràigare, a lu mudare cun seguresa, a lu mantènnere in funtzione pro sa gente chi l'impreat, e a traballare in iscuadra cun s'IA.","search":"Chirca una paràula…","none":"Peruna paràula currispondet.","close":"Serra","count":{"one":"{count} paràula","other":"{count} paràulas"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Fràigare"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Mudare cun seguresa"},{"id":"run","name":"🛎️ Gestire unu servìtziu"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ideas e traballu non ancora pianificados. Nudda inie benit traballadu fintzas a cando no passat a De fàghere."},{"id":"sprint","g":"agile","word":"Sprint","text":"Unu perìodu curtzu de traballu (a medas una o duas chidas) cun un'incùngiu de cartas cunvènidu de acabbare.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Unu puntu lestru: su chi cada cumpongiu at fatu, su chi faghet a pustis, e su chi lu firmat.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Una tàula cun colonnas (De fàghere, In cursu, Fatu) inue sas cartas andant dae manca a dereta a pizu a pizu chi su traballu andat in antis."},{"id":"wip","g":"agile","word":"Lìmite WIP","text":"Work in progress: su màssimu de cartas chi una colonna depet tènnere, gasi s'iscuadra acabbat sas cosas in antis de nde incumintzare àteras.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definitzione de Fatu","text":"Sa lista curtza de s'iscuadra de su chi cheret nàrrere “acabadu”, comente proadu e ispiegadu, in antis chi una carta lompat a tie. Sa gemella sua, sa Definitzione de Prontu, narat cando una carta est crara bastante pro incumintzare.","also":["Definition of Done","DoD","Definitzione de Prontu","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"Un'ograda a segus a comente traballat s'iscuadra, pro si pònnere de acordu subra una cosa de fàghere mègius. In AI-gile, una retro propònet una muda a sa manera de traballare de s'iscuadra, e tue naras Go o Non ancora.","also":["retrospetiva","retrospetivas"]},{"id":"swarm","g":"agile","word":"Isciamu","text":"Totus a manu: ogni iscuadra lassat s'àteru traballu pro agiudare in unu progetu urgente finas a cando est risòltu. Sos àteros progetos isetant in s'interis.","also":["isciamare","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Sa persone chi mantenet su traballu in movimentu: bidet sas cartas firmas, ispinghet sas iscuadras e ti ammentat su chi est isetende. In AI-gile, su Lead Scrum Master faghet custu in totu sos progetos.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Sa cartella de su progetu cun su còdighe e totu sa istòria de sos commit, a medas tenida fintzas in GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Una lìnea de traballu a banda in su còdighe, pro fàghere cambiamentos sena tocare sa versione printzipale.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Una fotografia sarvada de su còdighe, cun una nota curtza de su chi est cambiadu. Podes semper torrare a una.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Imbiare sas fotografias sarvadas (commits) dae custu computer a GitHub, gasi sunt sarvadas e cumpartzidas."},{"id":"merge","g":"build","word":"Merge","text":"Torrare a unire sos cambiamentos de una branch in sa versione printzipale."},{"id":"pr","g":"build","word":"Pull request","text":"Pedire chi sos cambiamentos de una branch siant verificados e fùndidos in sa versione printzipale.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Riordinare su còdighe sena mudare su chi faghet: documentos prus piticos, nùmenes prus craros, mancu repetitziones."},{"id":"bug","g":"build","word":"Bug","text":"Calicuna cosa chi no andat comente depet.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revisione de pares","text":"Unu segundu pàrigiu de ogros: un'àtera IA controllat su traballu de ogni carta in antis chi lompat a tie, gasi passant prus pagu errores.","also":["peer review","code review","revisione de su còdighe"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Proare unu traballu acabbadu pro verificare chi faghet su chi fiat istadu dimandadu, in antis de lu atzetare.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Est sa sigla de quality assurance, garantzia de calidade: sos controllos automàticos chi andant in antis chi carchi cosa andet in direta. Cando sa QA est ruja, calicuna cosa at faddidu, e no podet andare in direta finas a cando no est acontzada.","also":["controllos de calidade","quality assurance"]},{"id":"testpile","g":"test","word":"Pila de proas","text":"Sas cartas acabadas chi isetant chi las proes, una a pustis de s'àtera. Atzeta·nde una o torra·la in segus cun una nota, e nde essit sa chi sighit.","also":["pilas de proas","test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Pònnere una versione noa in lìnea, pro esempru in unu serbidore inue sa zente l'impreat."},{"id":"release","g":"change","word":"Lantzamentu","text":"Unu pachete de traballu acabadu, cun unu nòmine, chi andat in direta totu impare, cun pagas notas subra de su chi est cambiadu. 🚀 Lantzamentos iscriet sas notas dae sas cartas fatas.","also":["lantzamentos","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Torrare a s'ùrtima versione chi funtzionaiat cando una noa dat problemas. In AI-gile, custu faghet una lista de controllu cun sos passos pro annullare iscritos in ogni muda.","also":["torrare in segus","annullare","roll back"]},{"id":"live","g":"change","word":"In direta","text":"Sa versione vera chi sa gente impreat, e no una còpia pro proare sas cosas. Sos programadores li narant fintzas produtzione.","also":["produtzione","live"],"noTip":1},{"id":"change","g":"change","word":"Muda","text":"Una muda programmada a calicuna cosa chi sa gente b'at bisòngiu, iscrita in antis: ite, pro ite, su rìsicu, cando e comente annullare·la. Incumintza·nde una cun 🔀 Pedi una muda.","also":["mudas","rechesta de muda","change request"],"noTip":1},{"id":"risk","g":"change","word":"Rìsicu","text":"Calicuna cosa chi diat pòdere andare male, cun unu puntègiu pro cantu est probàbile e cantu diat èssere grave. ⚠️ Risicos los mantenet in una lista sola, dae su puntègiu prus artu, ognunu cun una data pro torrare a bìdere.","also":["rìsicos","registru de sos rìsicos"]},{"id":"chgwin","g":"change","word":"Ventana de muda","text":"Sos momentos in ue sas mudas podent andare in direta, comente unu martis a sero tranchillu. Foras de una ventana, una carta de muda no si podet acabare, francu chi siat un'emergèntzia.","also":["ventanas de muda","change window"]},{"id":"gonogo","g":"change","word":"Andat / Non andat","text":"Unu votu lestru pròpiu in antis chi una muda andet in direta: ogni persone chi la depet aprovare narat Andat o Non andat. Andat a in antis isceti cando sunt totus de acordu.","also":["go/no go","go-no-go","go / no go"]},{"id":"approval","g":"change","word":"Aprovatzione","text":"Isetare unu sì in antis chi su traballu incumintzet. Una carta chi pesat un'amigu, o una muda, isetat in ✅ Aprovatziones finas a cando no l'aprovas o no la refudas.","also":["aprovatziones"]},{"id":"quiettime","g":"change","word":"Tempus de calma","text":"Unu tretu de tempus, comente unu stream, una demo o su note, in ue nudda andat in direta. Sas iscuadras sighint a traballare e a proare, ma s'andare in direta isetat finas a cando acabat. In àteros logos li narant blocu de sas mudas.","also":["tempos de calma","blocu de sas mudas","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Servìtziu","text":"Calicuna cosa chi as fraigadu e chi sa gente b'at bisòngiu, comente unu situ o un'app, curada pro chi sigat a funtzionare. Sinna “Custu progetu est unu servìtziu” e nara ite oferit, chie l'impreat e chie est de guàrdia.","also":["servìtzios"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Controllu de funtzionamentu","text":"Unu controllu automàticu, ogni pagos minutos, chi su servìtziu tuo rispondet galu. Si faddit unas cantas bortas de sighidu, AI-gile aberit a sa sola una carta de incidente.","also":["uptime","tempus de funtzionamentu","uptime check"]},{"id":"statuspage","g":"run","word":"Pàgina de istadu","text":"Una pàgina pùblica chi mustrat si unu servìtziu funtzionat (birde, arantzu o ruju) cun s'ùrtimu agiornamentu, gasi sa gente chi l'impreat podet controllare imbetzes de pregontare.","also":["pàginas de istadu","status page"]},{"id":"desk","g":"run","word":"Banchu de assistèntzia","text":"Su logu in ue arribant sas dimandas e sas segnalatziones de sa gente chi impreat su servìtziu tuo. AI-gile ponet ognuna comente pedidu, incidente o idea, e lu narat cando paret una cosa giai segnalada.","also":["banchos de assistèntzia","banchu","service desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Pedidu de servìtziu","text":"Calicunu chi pedit una cosa normale, comente unu contu nou o unu pagu de agiudu, imbetzes de segnalare chi calicuna cosa est segada. Isetat su turnu suo; un'incidente passat in antis.","also":["pedidos de servìtziu","pedidu"]},{"id":"incident","g":"run","word":"Incidente","text":"Calicuna cosa chi no funtzionat como pro sa gente chi l'impreat, comente su situ chi est rutu. Una carta 🔥 incidente passat in antis de sa fila: torrare a lu fàghere funtzionare benit primu.","also":["incidentes","guastu"]},{"id":"major","g":"run","word":"Incidente mannu","text":"Un'incidente grussu: medas persones tocadas, o dinare o datos in perìculu. Unu butone ponet totu sas iscuadras in subra (isciamu), ischidat chie est de guàrdia e pedit un'agiornamentu de istadu ogni 30 minutos.","also":["incidentes mannos","major incident"]},{"id":"oncall","g":"run","word":"De guàrdia","text":"Èssere sa persone chi rispondet cando calicuna cosa si segat, fintzas de note. Ogni servìtziu tenet unu cumpàngiu de iscuadra de guàrdia, chi est ischidadu primu pro sos incidentes suos.","also":["guàrdia","on call","on-call"]},{"id":"replyby","g":"run","word":"Tempus de risposta","text":"Cantu tempus una carta podet isetare una prima risposta, pro esempru un'ora pro un'incidente. A pustis tenet un'orologiu ruju, gasi nudda abarrat ismentigadu a sa muda. Li narant fintzas obietivu de risposta.","also":["tempos de risposta","obietivu de risposta"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un'ograda curtza a segus a pustis de un'incidente: ite est sutzèdidu, ite at agiudadu e ite cambiare, sena dare sa culpa a nemos. Un'incidente no si podet serrare sena unu post-mortem.","also":["post-mortems","postmortem","revisione a pustis de s'incidente"]},{"id":"problem","g":"run","word":"Problema","text":"Sa causa cuada in segus de unu o prus incidentes. Una carta 🧩 problema agrupat sos incidentes chi sighint a torrare, gasi sa causa est agatada e acontzada pro semper.","also":["problemas"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa de fundu","text":"Su motivu beru pro ite una cosa s'est segada, e no isceti su chi as bidu andende male. Acontza sa causa de fundu e s'incidente no torrat prus.","also":["causas de fundu","root cause"]},{"id":"workaround","g":"run","word":"Soluzione provisòria","text":"Una manera de mantènnere sas cosas in funtzione finas a cando s'acontzu beru est prontu, comente torrare a aviare una cosa cando s'arresta. Est iscrita in sa carta de su problema, gasi nemos la depet torrare a agatare.","also":["soluziones provisòrias","workaround"]},{"id":"knownerror","g":"run","word":"Errore connotu","text":"Unu problema chi nde connoschimus sa causa e chi tenet una soluzione provisòria, ma no est galu acontzadu. 🧩 Errores connotos los elencat, gasi totus impreant sa soluzione provisòria imbetzes de torrare a chircare.","also":["errores connotos","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Istrutziones passu pro passu pro acontzare unu tipu de problema connotu, gasi si faghet semper a sa matessi manera, a lestru. A pustis de un'incidente mannu, s'iscuadra nde podet propònnere unu pro chi tue nde des s'OK.","also":["runbooks","istrutziones operativas"]},{"id":"ci","g":"run","word":"Elementu de cunfiguratzione","text":"Una cosa de sa cale dipendet su servìtziu tuo, comente unu serbidore, unu domìniu, unu tzertificadu, una crae o unu fornidore. 🗂️ Elementos de cunfiguratzione los elencat pro ogni servìtziu, gasi bides ite tocat un'incidente e ite tocat a rinnovare o a nde fàghere una còpia de seguresa.","also":["elementos de cunfiguratzione"]},{"id":"expiry","g":"run","word":"Data de iscadèntzia","text":"AI-gile tenet in ogru datas comente cando iscadit unu tzertificadu o unu domìniu. 30 dies in antis de sa data faghet una carta pro lu rinnovare, gasi nudda si firmat a s'ispensada.","also":["datas de iscadèntzia","iscadèntzia","controllu de iscadèntzias"]},{"id":"backup","g":"run","word":"Còpia de seguresa","text":"Una còpia sarvada de sos datos tuos de prima, pro la pòdere impreare si carchi cosa si perdet o si guastat. AI-gile faghet ogni die una còpia de seguresa de sos tabellones tuos.","also":["còpias de seguresa","backup","backups"]},{"id":"restore","g":"run","word":"Riprìstinu","text":"Torrare a pònnere sos datos dae una còpia de seguresa. Una còpia contat a beru isceti cando ischis chi si podet riprìstinare, duncas balet sa pena de lu proare onni tantu.","also":["riprìstina","riprìstinadu","restore"]},{"id":"svcreview","g":"run","word":"Revisione de su servìtziu","text":"Un'ograda a pustis a unu mese de unu servìtziu: incidentes abertos e acontzados, cantu a lestru sa gente at tentu una risposta, funtzionamentu e token impreados. Sa Revisione mensile lu mustrat pro ogni servìtziu.","also":["revisiones de su servìtziu","revisione mensile","revisiones mensiles"]},{"id":"accessreview","g":"run","word":"Revisione de atzessu","text":"Controllare ogni 90 dies chie podet galu intrare: ligòngios de cumpartzidura, ròles de sos amigos e segretos sarvados. Ognunu lu mantenes o lu bogas, gasi s'atzessu betzu no abarrat a s'ismentigu.","also":["revisiones de atzessu"]},{"id":"improvements","g":"run","word":"Lista de megioramentos","text":"Totu su chi s'iscuadra at detzìdidu de megiorare, in unu logu ebbia: cussìgios de sa retro, atziones de sas revisiones e acontzos de problemas, ognunu cun s'istadu suo. Dda agatas in 📈 Megioramentos.","also":["listas de megioramentos","megioramentos"]},{"id":"tokencap","g":"run","word":"Lìmite de token","text":"Unu lìmite mensile de sos token chi sos agentes de unu servìtziu podent impreare. A su 80% retzis un'avisu; a su 100% su traballu issoro in segundu pianu isetat finas a su mese chi benit o finas a cando no artzias su lìmite.","also":["lìmites de token","lìmite mensile de token"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agente","text":"Un'IA chi traballat sola in unu cumandu: leghet su còdighe, faghet cambiamentos, esecutat controllos, e ti torrat informe.","also":["agentes"]},{"id":"token","g":"ai","word":"Token","text":"S'unidade cun sa cale si contat s'impreu de s'IA: a pagu prus o mancu unas cantas lìteras de testu leghidas o iscritas. Mancu token, prus pianu chi abarrat.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Unu cumandu piticu chi girat sou a unu momentu dadu, pro es. cando una sessione IA incumintzat, gasi s'iscuadra intendet sos cummentos tuos.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
